from typing import Any, Dict, Optional

from pydantic import BaseModel, ConfigDict, Field


class MCPOutboundCallContext(BaseModel):
    """Read-only context passed to an MCP / custom-tool credential hook.

    Rasa builds one of these immediately before an outbound MCP tool call
    (flow direct MCP or ReAct external MCP) or a ReAct custom-tool call and
    passes it to the hook. The hook uses ``sender_id`` (and optionally the
    other fields) to look up and decrypt credentials from an external secret
    store, then returns an :class:`OutboundCallResult` whose ``metadata`` Rasa
    merges into the outbound call metadata (MCP ``_meta`` or
    ``AgentToolContext.metadata``).

    Path-specific fields that do not apply to a given call are ``None``.
    """

    model_config = ConfigDict(frozen=True)

    sender_id: str = Field(
        ...,
        description=(
            "Conversation id. Flow MCP uses `tracker.sender_id`; agents use "
            "`agent_input.recipient_id`. Use this as the secret-store lookup key."
        ),
    )
    server_name: Optional[str] = Field(
        default=None,
        description=(
            "MCP server name for flow / ReAct external MCP tool calls; "
            "None for custom tools (no server)."
        ),
    )
    tool_name: str = Field(
        ...,
        description=(
            "Tool name being called. `step.call` for flow MCP, the MCP tool "
            "name for ReAct, or the custom tool name for custom tools."
        ),
    )
    flow_id: Optional[str] = Field(
        default=None,
        description="Executing flow id for flow direct MCP; otherwise None.",
    )
    step_id: Optional[str] = Field(
        default=None,
        description="MCP `call` step id for flow direct MCP; otherwise None.",
    )
    agent_id: Optional[str] = Field(
        default=None,
        description="Configured sub-agent id for ReAct agent calls; otherwise None.",
    )


class A2AOutboundCallContext(BaseModel):
    """Read-only context passed to an outbound A2A credential hook.

    Rasa builds one of these immediately before an outbound A2A
    ``message/send`` or ``message/stream`` and passes it to the hook. The hook
    returns an :class:`OutboundCallResult` whose ``metadata`` Rasa merges into
    the outbound ``Message.metadata`` (never ``parts`` or the top-level
    ``context_id`` / ``task_id``).
    """

    model_config = ConfigDict(frozen=True)

    sender_id: str = Field(
        ...,
        description=(
            "Conversation id (`agent_input.recipient_id`). Use this as the "
            "secret-store lookup key."
        ),
    )
    agent_id: str = Field(
        ...,
        description="Configured sub-agent id (`agent_input.id`).",
    )
    context_id: Optional[str] = Field(
        default=None,
        description="A2A context id (read-only; hook must not overwrite).",
    )
    task_id: Optional[str] = Field(
        default=None,
        description="A2A task id (read-only; hook must not overwrite).",
    )
    turn_metadata: Dict[str, Any] = Field(
        default_factory=dict,
        description=(
            "Snapshot of existing non-secret turn metadata (`agent_input.metadata`), "
            "read-only input to the hook. Mutations do not affect `agent_input`."
        ),
    )
